begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('13100000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'rfq-chat-'||i||'@test.invalid','{}' from generate_series(1,6)i;
insert into public.profile_roles(profile_id,role_id) select ('13100000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,case when i=1 then 'administrator' when i in(2,3) then 'sales' else 'sales_manager' end from generate_series(1,6)i;
update public.profiles set display_name='Sales Manager' where id='13100000-0000-0000-0000-000000000004';
insert into public.sales_desk_sales_codes(id,code) values('13100000-0000-0000-0001-000000000001','CHAT-A');
update public.profiles set sales_code='CHAT-A' where id='13100000-0000-0000-0000-000000000002';
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values ('13100000-0000-0000-0000-000000000006','sales_desk','sales_desk.receive_rfq_notifications',false);
insert into public.sales_desk_statuses(id,name,is_closed,metric_category) values ('13100000-0000-0000-0001-000000000002','Chat Complete',true,'completed');
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000001","role":"authenticated"}';
create temp table chat_rfq as select (public.create_sales_desk_rfq(jsonb_build_object('customer_name','Chat RFQ','media_platform_id',(select id from public.sales_desk_media_platforms limit 1),'sales_code_id','13100000-0000-0000-0001-000000000001'))->>'id')::uuid id;
grant select on chat_rfq to authenticated;
select is((select completed_at from public.sales_desk_rfqs where id=(select id from chat_rfq)),null::timestamptz,'open RFQ has no completion timestamp');
set local role authenticated;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000004","role":"authenticated"}';
select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'NO ATTACHMENT','13100000-0000-0000-0002-000000000001');
select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'NO ATTACHMENT','13100000-0000-0000-0002-000000000001');
select throws_ok($$select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'DIFFERENT','13100000-0000-0000-0002-000000000001')$$,'22023',null,'retry cannot change message');
reset role;
select is((select count(*) from public.chat_messages where rfq_id=(select id from chat_rfq)),1::bigint,'manager sends one linked chat despite retry');
select is((select count(*) from public.user_notifications where kind='rfq_chat_update'),1::bigint,'notification retry is idempotent');
select is((select description from public.user_notifications where kind='rfq_chat_update'),E'NO ATTACHMENT\nSales Manager','notification contains message and authenticated sender name');
set local role authenticated;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000002","role":"authenticated"}';
select is((select unread_count from public.chat_list_conversations() limit 1),1::bigint,'new RFQ chat is unread until opened');
select ok((select rfq_id=(select id from chat_rfq) from public.chat_list_messages((select conversation_id from public.chat_list_conversations() limit 1))),'recipient receives structured RFQ link');
select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'ATTACHED NOW','13100000-0000-0000-0002-000000000002');
select throws_ok($$select public.update_sales_desk_rfq((select id from chat_rfq),' {"completed_at":"2020-01-01"}')$$,'42501',null,'consultant cannot forge completion time');
select public.update_sales_desk_rfq((select id from chat_rfq),'{"status_id":"13100000-0000-0000-0001-000000000002"}');
select ok((select completed_at is not null from public.sales_desk_rfqs where id=(select id from chat_rfq)),'consultant status change records completion time automatically');
reset role;
select is((select count(*) from public.user_notifications where kind='rfq_chat_update' and description like 'ATTACHED NOW%'),2::bigint,'consultant sends to all enabled managers');
select is((select count(*) from public.user_notifications where kind='rfq_chat_update' and user_id='13100000-0000-0000-0000-000000000006'),0::bigint,'disabled manager is excluded');
set local role authenticated;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000003","role":"authenticated"}';
select throws_ok($$select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'Not mine','13100000-0000-0000-0002-000000000003')$$,'42501',null,'another consultant cannot send for someone else');
reset role;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000001","role":"authenticated"}';
select public.update_sales_desk_rfq((select id from chat_rfq),'{"completed_at":"2026-10-30T12:00:00Z"}');
select is((select completed_at from public.sales_desk_rfqs where id=(select id from chat_rfq)),'2026-10-30T12:00:00Z'::timestamptz,'manager may correct completion time');
select public.update_sales_desk_rfq((select id from chat_rfq),jsonb_build_object('status_id',(select id from public.sales_desk_statuses where semantic_key='in_progress' limit 1)));
select is((select completed_at from public.sales_desk_rfqs where id=(select id from chat_rfq)),null::timestamptz,'reopening clears completion time');
update public.application_user_permission_overrides set enabled=false where permission_key='sales_desk.receive_rfq_notifications';
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values ('13100000-0000-0000-0000-000000000004','sales_desk','sales_desk.receive_rfq_notifications',false),('13100000-0000-0000-0000-000000000005','sales_desk','sales_desk.receive_rfq_notifications',false);
set local role authenticated;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'No managers','13100000-0000-0000-0002-000000000004')$$,'22023',null,'no enabled manager gives an actionable error');
reset role;
select is((select count(*) from public.chat_messages where rfq_id=(select id from chat_rfq)),3::bigint,'failed dispatch creates no partial messages');
select ok(not has_function_privilege('anon','public.send_rfq_chat_update(text,text,uuid)','execute'),'signed out users cannot send updates');
select ok(not has_table_privilege('authenticated','public.rfq_chat_dispatches','insert'),'browser cannot forge dispatch receipts');
insert into public.application_user_permission_overrides(profile_id,app_id,permission_key,enabled) values ('13100000-0000-0000-0000-000000000004','sales_desk','sales_desk.send_rfq_update',false);
set local role authenticated;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000004","role":"authenticated"}';
select throws_ok($$select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'DENIED','13100000-0000-0000-0002-000000000006')$$,'42501',null,'send permission override is enforced on the server');
reset role;
delete from public.application_user_permission_overrides where profile_id='13100000-0000-0000-0000-000000000004' and permission_key='sales_desk.send_rfq_update';
-- A completion correction is a business edit and invalidates a previous approval.
update public.sales_desk_rfqs set status_id='13100000-0000-0000-0001-000000000002',approval_state='approved' where id=(select id from chat_rfq);
update public.sales_desk_rfqs set approval_state='approved' where id=(select id from chat_rfq);
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000001","role":"authenticated"}';
select public.update_sales_desk_rfq((select id from chat_rfq),'{"completed_at":"2026-10-29T12:00:00Z"}');
select is((select approval_state from public.sales_desk_rfqs where id=(select id from chat_rfq)),'not_requested','completion correction invalidates approval');
select ok(exists(select 1 from public.sales_desk_rfq_audit where rfq_id=(select id from chat_rfq) and changes->'changed' ? 'completed_at'),'completion corrections are audited');
-- Failure after a chat write must roll back the entire dispatch.
create function pg_temp.fail_rfq_chat_notification() returns trigger language plpgsql as $$begin if new.kind='rfq_chat_update' then raise exception 'test notification failure';end if;return new;end$$;
create trigger fail_rfq_chat_notification before insert on public.user_notifications for each row execute function pg_temp.fail_rfq_chat_notification();
set local role authenticated;
set local request.jwt.claims='{"sub":"13100000-0000-0000-0000-000000000004","role":"authenticated"}';
select throws_ok($$select public.send_rfq_chat_update((select rfq_no from public.sales_desk_rfqs where id=(select id from chat_rfq)),'ROLLBACK','13100000-0000-0000-0002-000000000005')$$,'P0001','test notification failure','notification failure rolls back dispatch');
reset role;
select is((select count(*) from public.chat_messages where body='ROLLBACK'),0::bigint,'no partial chat survives a notification failure');
select is((select count(*) from public.rfq_chat_dispatches where client_id='13100000-0000-0000-0002-000000000005'),0::bigint,'failed transaction leaves no retry receipt');
select * from finish();
rollback;
